import type { WisdomArticle } from "./types";

/** Articles sourced verbatim from temp-content/p4.txt (link-scrubbed, headings normalized) */
export const p4Articles: WisdomArticle[] = [
  {
    id: "planetary-strengths",
    section: "planets",
    title: { en: `Planetary Strengths or Powers`, ja: `Planetary Strengths or Powers` },
    related: ["natural-benefics-malefics","planetary-aspects","twelve-houses"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Planetary Strengths or Powers`, ja: `Planetary Strengths or Powers` } },
      { type: "paragraph", text: { en: `Summary: This article covers one of the most important aspects of chart interpretation—assessing the "strength," "power," or "status" of a planet based on its sign placement in a birth chart. It also explains the principles of sign ownership (rulership), the concepts of planetary "friends" and "enemies," and examines how retrograde motion, combustion, Vargottama status, divisional charts, and planetary war influence planetary strength.`, ja: `Summary: This article covers one of the most important aspects of chart interpretation—assessing the "strength," "power," or "status" of a planet based on its sign placement in a birth chart. It also explains the principles of sign ownership (rulership), the concepts of planetary "friends" and "enemies," and examines how retrograde motion, combustion, Vargottama status, divisional charts, and planetary war influence planetary strength.` } },
      { type: "heading", level: 3, text: { en: `Sign ‘Ownership’ or ‘Rulership’ Principles`, ja: `Sign ‘Ownership’ or ‘Rulership’ Principles` } },
      { type: "paragraph", text: { en: `The Vedic seers assigned each sign of the zodiac to a particular planet.`, ja: `The Vedic seers assigned each sign of the zodiac to a particular planet.` } },
      { type: "heading", level: 3, text: { en: `Sign Ownership or Rulership by Planets in Jyotish`, ja: `Sign Ownership or Rulership by Planets in Jyotish` } },
      { type: "paragraph", text: { en: `For example, from the chart above we can see that the Sun is associated with the sign Leo. Therefore, the Sun is said to be the Owner or Ruler of Leo (sidereal).`, ja: `For example, from the chart above we can see that the Sun is associated with the sign Leo. Therefore, the Sun is said to be the Owner or Ruler of Leo (sidereal).` } },
      { type: "paragraph", text: { en: `Notice that the Sun and Moon each rule only one sign, whereas the remaining visible planets—Mars, Mercury, Jupiter, Venus, and Saturn—each rule two signs. Thus, Jupiter rules Sagittarius and Pisces, Mercury rules Gemini and Virgo, and so on.`, ja: `Notice that the Sun and Moon each rule only one sign, whereas the remaining visible planets—Mars, Mercury, Jupiter, Venus, and Saturn—each rule two signs. Thus, Jupiter rules Sagittarius and Pisces, Mercury rules Gemini and Virgo, and so on.` } },
      { type: "paragraph", text: { en: `It is important to note that Rahu and Ketu do not own or rule any zodiac sign.`, ja: `It is important to note that Rahu and Ketu do not own or rule any zodiac sign.` } },
      { type: "heading", level: 3, text: { en: `Planetary ‘Strengths’ or ‘Powers’ – by Sign Placement`, ja: `Planetary ‘Strengths’ or ‘Powers’ – by Sign Placement` } },
      { type: "paragraph", text: { en: `In Jyotish, evaluating the strength or power of a planet is a fundamental part of chart interpretation.`, ja: `In Jyotish, evaluating the strength or power of a planet is a fundamental part of chart interpretation.` } },
      { type: "paragraph", text: { en: `A planet regarded as strong tends to produce benefits and indicates positive returning karma. In general terms, a strong planet is usually considered a beneficial planet.`, ja: `A planet regarded as strong tends to produce benefits and indicates positive returning karma. In general terms, a strong planet is usually considered a beneficial planet.` } },
      { type: "paragraph", text: { en: `There are two primary ways in which a strong planet produces positive results:`, ja: `There are two primary ways in which a strong planet produces positive results:` } },
      { type: "heading", level: 3, text: { en: `1. Benefits Through the Planet’s Natural Indications`, ja: `1. Benefits Through the Planet’s Natural Indications` } },
      { type: "paragraph", text: { en: `A strong planet supports the life areas represented by its natural associations or Karakas.`, ja: `A strong planet supports the life areas represented by its natural associations or Karakas.` } },
      { type: "paragraph", text: { en: `For example, the Sun naturally signifies health, vitality, self-esteem, authority, power, and the relationship with one's father. Therefore, when the Sun is strong in a chart, we generally expect positive outcomes in these areas.`, ja: `For example, the Sun naturally signifies health, vitality, self-esteem, authority, power, and the relationship with one's father. Therefore, when the Sun is strong in a chart, we generally expect positive outcomes in these areas.` } },
      { type: "paragraph", text: { en: `Similarly, the Moon naturally represents the mind, emotions, memory, and mental well-being. A strong Moon would therefore support emotional balance, memory, and mental stability.`, ja: `Similarly, the Moon naturally represents the mind, emotions, memory, and mental well-being. A strong Moon would therefore support emotional balance, memory, and mental stability.` } },
      { type: "heading", level: 3, text: { en: `2. Benefits Through the Houses the Planet Rules`, ja: `2. Benefits Through the Houses the Planet Rules` } },
      { type: "paragraph", text: { en: `A strong planet also supports the houses associated with the signs that it owns or rules.`, ja: `A strong planet also supports the houses associated with the signs that it owns or rules.` } },
      { type: "paragraph", text: { en: `In Jyotish, each house encompasses an entire zodiac sign. Consequently, every house is connected to a particular sign and therefore to a ruling planet. When constructing a horoscope, the Ascendant sign becomes the first house.`, ja: `In Jyotish, each house encompasses an entire zodiac sign. Consequently, every house is connected to a particular sign and therefore to a ruling planet. When constructing a horoscope, the Ascendant sign becomes the first house.` } },
      { type: "paragraph", text: { en: `For example, if a person has Aries rising, Aries becomes the first house. To examine matters relating to children, we look to the 5th house. Counting clockwise from Aries, Leo becomes the 5th house. Since the Sun rules Leo, a strong Sun would positively influence the affairs of the 5th house, including children, education, intelligence, and creativity.`, ja: `For example, if a person has Aries rising, Aries becomes the first house. To examine matters relating to children, we look to the 5th house. Counting clockwise from Aries, Leo becomes the 5th house. Since the Sun rules Leo, a strong Sun would positively influence the affairs of the 5th house, including children, education, intelligence, and creativity.` } },
      { type: "paragraph", text: { en: `This support would come in addition to the Sun's natural indications such as health, confidence, and authority.`, ja: `This support would come in addition to the Sun's natural indications such as health, confidence, and authority.` } },
      { type: "paragraph", text: { en: `To summarise, when a planet is strong, both its natural indications and the houses it rules receive support and benefit.`, ja: `To summarise, when a planet is strong, both its natural indications and the houses it rules receive support and benefit.` } },
      { type: "heading", level: 3, text: { en: `Assessing Planetary Strength from Sign Placement`, ja: `Assessing Planetary Strength from Sign Placement` } },
      { type: "paragraph", text: { en: `Although planetary strength can be measured in numerous ways, one of the most important methods is by examining the zodiac sign in which the planet is placed.`, ja: `Although planetary strength can be measured in numerous ways, one of the most important methods is by examining the zodiac sign in which the planet is placed.` } },
      { type: "paragraph", text: { en: `In some cases, the specific degree within a sign can also affect the level of strength.`, ja: `In some cases, the specific degree within a sign can also affect the level of strength.` } },
      { type: "paragraph", text: { en: `Vedic Astrology teaches that certain signs empower a planet and enable it to produce beneficial results, while other signs weaken it and may indicate challenges or more difficult returning karmas. Therefore, a planet's sign placement plays a major role in determining its strength.`, ja: `Vedic Astrology teaches that certain signs empower a planet and enable it to produce beneficial results, while other signs weaken it and may indicate challenges or more difficult returning karmas. Therefore, a planet's sign placement plays a major role in determining its strength.` } },
      { type: "paragraph", text: { en: `When first learning astrology, a useful approach is to identify whether each planet falls into one of four principal categories of strength.`, ja: `When first learning astrology, a useful approach is to identify whether each planet falls into one of four principal categories of strength.` } },
      { type: "paragraph", text: { en: `These are:`, ja: `These are:` } },
      { type: "paragraph", text: { en: `• Exalted`, ja: `• Exalted` } },
      { type: "paragraph", text: { en: `• Moolatrikona`, ja: `• Moolatrikona` } },
      { type: "paragraph", text: { en: `• Own Sign`, ja: `• Own Sign` } },
      { type: "paragraph", text: { en: `• Debilitated (or Fallen)`, ja: `• Debilitated (or Fallen)` } },
      { type: "paragraph", text: { en: `Exalted is the strongest condition, while Debilitated is the weakest. A planet placed in its Own Sign is generally considered strong and supportive.`, ja: `Exalted is the strongest condition, while Debilitated is the weakest. A planet placed in its Own Sign is generally considered strong and supportive.` } },
      { type: "paragraph", text: { en: `The state known as Moolatrikona has no direct English equivalent but is regarded as stronger than Own Sign and slightly below Exaltation.`, ja: `The state known as Moolatrikona has no direct English equivalent but is regarded as stronger than Own Sign and slightly below Exaltation.` } },
      { type: "paragraph", text: { en: `The sign of debilitation is always located exactly 180 degrees opposite the sign of exaltation.`, ja: `The sign of debilitation is always located exactly 180 degrees opposite the sign of exaltation.` } },
      { type: "paragraph", text: { en: `For example, Venus is naturally benefic. When Venus occupies Pisces, its sign of exaltation, it can produce significant benefits through both its natural indications and the houses associated with Taurus and Libra, the signs it rules.`, ja: `For example, Venus is naturally benefic. When Venus occupies Pisces, its sign of exaltation, it can produce significant benefits through both its natural indications and the houses associated with Taurus and Libra, the signs it rules.` } },
      { type: "paragraph", text: { en: `However, when Venus occupies Virgo, its sign of debilitation, its ability to provide positive results is greatly reduced.`, ja: `However, when Venus occupies Virgo, its sign of debilitation, its ability to provide positive results is greatly reduced.` } },
      { type: "paragraph", text: { en: `A planet's capacity to produce beneficial outcomes therefore varies according to its strength, and its strength depends largely upon the sign in which it is placed.`, ja: `A planet's capacity to produce beneficial outcomes therefore varies according to its strength, and its strength depends largely upon the sign in which it is placed.` } },
      { type: "paragraph", text: { en: `The following sections provide the traditional strength classifications.`, ja: `The following sections provide the traditional strength classifications.` } },
      { type: "heading", level: 3, text: { en: `Planetary Strengths or Powers by Sign Placement`, ja: `Planetary Strengths or Powers by Sign Placement` } },
      { type: "heading", level: 3, text: { en: `Sun (Surya)`, ja: `Sun (Surya)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Aries (maximum strength at 10° Aries)`, ja: `• Exalted Sign: Aries (maximum strength at 10° Aries)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Leo 0°–20°`, ja: `• Moolatrikona Sign: Leo 0°–20°` } },
      { type: "paragraph", text: { en: `• Own Sign: Leo 20°–30°`, ja: `• Own Sign: Leo 20°–30°` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Libra (maximum weakness at 10° Libra)`, ja: `• Debilitated Sign: Libra (maximum weakness at 10° Libra)` } },
      { type: "heading", level: 3, text: { en: `Moon (Chandra)`, ja: `Moon (Chandra)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Taurus 0°–3°`, ja: `• Exalted Sign: Taurus 0°–3°` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Taurus 3°–30°`, ja: `• Moolatrikona Sign: Taurus 3°–30°` } },
      { type: "paragraph", text: { en: `• Own Sign: Cancer`, ja: `• Own Sign: Cancer` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Scorpio (maximum weakness at 3° Scorpio)`, ja: `• Debilitated Sign: Scorpio (maximum weakness at 3° Scorpio)` } },
      { type: "heading", level: 3, text: { en: `Mars (Mangala)`, ja: `Mars (Mangala)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Capricorn (maximum strength at 28° Capricorn)`, ja: `• Exalted Sign: Capricorn (maximum strength at 28° Capricorn)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Aries 0°–12°`, ja: `• Moolatrikona Sign: Aries 0°–12°` } },
      { type: "paragraph", text: { en: `• Own Signs: Aries 12°–30° and Scorpio`, ja: `• Own Signs: Aries 12°–30° and Scorpio` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Cancer (maximum weakness at 28° Cancer)`, ja: `• Debilitated Sign: Cancer (maximum weakness at 28° Cancer)` } },
      { type: "heading", level: 3, text: { en: `Mercury (Buddha)`, ja: `Mercury (Buddha)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Virgo 0°–15° (maximum strength at 15° Virgo)`, ja: `• Exalted Sign: Virgo 0°–15° (maximum strength at 15° Virgo)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Virgo 16°–20°`, ja: `• Moolatrikona Sign: Virgo 16°–20°` } },
      { type: "paragraph", text: { en: `• Own Signs: Virgo 20°–30° and Gemini`, ja: `• Own Signs: Virgo 20°–30° and Gemini` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Pisces (maximum weakness at 15° Pisces)`, ja: `• Debilitated Sign: Pisces (maximum weakness at 15° Pisces)` } },
      { type: "heading", level: 3, text: { en: `Jupiter (Guru)`, ja: `Jupiter (Guru)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Cancer (maximum strength at 5° Cancer)`, ja: `• Exalted Sign: Cancer (maximum strength at 5° Cancer)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Sagittarius 0°–10°`, ja: `• Moolatrikona Sign: Sagittarius 0°–10°` } },
      { type: "paragraph", text: { en: `• Own Signs: Sagittarius 10°–30° and Pisces`, ja: `• Own Signs: Sagittarius 10°–30° and Pisces` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Capricorn (maximum weakness at 5° Capricorn)`, ja: `• Debilitated Sign: Capricorn (maximum weakness at 5° Capricorn)` } },
      { type: "heading", level: 3, text: { en: `Venus (Shukra)`, ja: `Venus (Shukra)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Pisces (maximum strength at 27° Pisces)`, ja: `• Exalted Sign: Pisces (maximum strength at 27° Pisces)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Libra 0°–15° and Taurus`, ja: `• Moolatrikona Sign: Libra 0°–15° and Taurus` } },
      { type: "paragraph", text: { en: `• Own Signs: Taurus 15°–30° and Libra`, ja: `• Own Signs: Taurus 15°–30° and Libra` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Virgo (maximum weakness at 27° Virgo)`, ja: `• Debilitated Sign: Virgo (maximum weakness at 27° Virgo)` } },
      { type: "heading", level: 3, text: { en: `Saturn (Shani)`, ja: `Saturn (Shani)` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Libra (maximum strength at 20° Libra)`, ja: `• Exalted Sign: Libra (maximum strength at 20° Libra)` } },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Aquarius 0°–15°`, ja: `• Moolatrikona Sign: Aquarius 0°–15°` } },
      { type: "paragraph", text: { en: `• Own Signs: Aquarius 15°–30° and Capricorn`, ja: `• Own Signs: Aquarius 15°–30° and Capricorn` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Aries (maximum weakness at 20° Aries)`, ja: `• Debilitated Sign: Aries (maximum weakness at 20° Aries)` } },
      { type: "heading", level: 3, text: { en: `Rahu`, ja: `Rahu` } },
      { type: "paragraph", text: { en: `There is considerable variation among the ancient authorities regarding the signs where Rahu and Ketu are strongest or weakest. The following placements are based on the most reliable sources available.`, ja: `There is considerable variation among the ancient authorities regarding the signs where Rahu and Ketu are strongest or weakest. The following placements are based on the most reliable sources available.` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Taurus`, ja: `• Exalted Sign: Taurus` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Scorpio`, ja: `• Debilitated Sign: Scorpio` } },
      { type: "heading", level: 3, text: { en: `Ketu`, ja: `Ketu` } },
      { type: "paragraph", text: { en: `• Exalted Sign: Scorpio`, ja: `• Exalted Sign: Scorpio` } },
      { type: "paragraph", text: { en: `• Debilitated Sign: Taurus`, ja: `• Debilitated Sign: Taurus` } },
      { type: "heading", level: 3, text: { en: `Additional Measures of Strength – ‘Friends’ and ‘Enemies’`, ja: `Additional Measures of Strength – ‘Friends’ and ‘Enemies’` } },
      { type: "paragraph", text: { en: `Experienced astrologers use additional categories that lie between the states of Own Sign and Debilitation. These provide a more refined assessment of planetary condition.`, ja: `Experienced astrologers use additional categories that lie between the states of Own Sign and Debilitation. These provide a more refined assessment of planetary condition.` } },
      { type: "paragraph", text: { en: `Three important intermediate categories are:`, ja: `Three important intermediate categories are:` } },
      { type: "paragraph", text: { en: `• Friend`, ja: `• Friend` } },
      { type: "paragraph", text: { en: `• Neutral`, ja: `• Neutral` } },
      { type: "paragraph", text: { en: `• Enemy`, ja: `• Enemy` } },
      { type: "paragraph", text: { en: `A planet placed in a sign ruled by a friendly planet tends to function well, whereas a planet occupying the sign of an enemy is weakened.`, ja: `A planet placed in a sign ruled by a friendly planet tends to function well, whereas a planet occupying the sign of an enemy is weakened.` } },
      { type: "paragraph", text: { en: `Of course, planets do not literally have friends or enemies. These terms simply indicate that certain planetary environments are more supportive than others. For example, Venus is considered less comfortable and therefore less productive when placed in a sign ruled by an enemy such as the Sun.`, ja: `Of course, planets do not literally have friends or enemies. These terms simply indicate that certain planetary environments are more supportive than others. For example, Venus is considered less comfortable and therefore less productive when placed in a sign ruled by an enemy such as the Sun.` } },
      { type: "paragraph", text: { en: `In addition to these permanent friendship categories, Jyotish also recognises temporary friendships based upon the relative positions of planets within a chart. These create two additional classifications:`, ja: `In addition to these permanent friendship categories, Jyotish also recognises temporary friendships based upon the relative positions of planets within a chart. These create two additional classifications:` } },
      { type: "paragraph", text: { en: `• Great Friend`, ja: `• Great Friend` } },
      { type: "paragraph", text: { en: `• Great Enemy`, ja: `• Great Enemy` } },
      { type: "paragraph", text: { en: `Although charts and rules exist to determine these relationships, they can be challenging for beginners to memorise. Fortunately, most good Vedic Astrology software calculates these conditions automatically.`, ja: `Although charts and rules exist to determine these relationships, they can be challenging for beginners to memorise. Fortunately, most good Vedic Astrology software calculates these conditions automatically.` } },
      { type: "paragraph", text: { en: `Together with the categories of Exalted, Moolatrikona, Own Sign, and Debilitated, these friendship classifications form the primary planetary states or Avasthas used in chart interpretation.`, ja: `Together with the categories of Exalted, Moolatrikona, Own Sign, and Debilitated, these friendship classifications form the primary planetary states or Avasthas used in chart interpretation.` } },
      { type: "paragraph", text: { en: `For a complete analysis, all nine categories should be considered. However, beginners can gain surprisingly accurate insights simply by focusing on the four major states: Exalted, Moolatrikona, Own Sign, and Debilitated.`, ja: `For a complete analysis, all nine categories should be considered. However, beginners can gain surprisingly accurate insights simply by focusing on the four major states: Exalted, Moolatrikona, Own Sign, and Debilitated.` } },
      { type: "paragraph", text: { en: `The sage Parashara quantified the relative benefits of these states as follows:`, ja: `The sage Parashara quantified the relative benefits of these states as follows:` } },
      { type: "paragraph", text: { en: `• Exalted: 100%`, ja: `• Exalted: 100%` } },
      { type: "paragraph", text: { en: `• Moolatrikona: 75%`, ja: `• Moolatrikona: 75%` } },
      { type: "paragraph", text: { en: `• Own Sign: 50%`, ja: `• Own Sign: 50%` } },
      { type: "paragraph", text: { en: `• Friendly Sign: 25%`, ja: `• Friendly Sign: 25%` } },
      { type: "paragraph", text: { en: `• Neutral Sign: 12%`, ja: `• Neutral Sign: 12%` } },
      { type: "paragraph", text: { en: `• Fallen/Enemy Sign: 0%`, ja: `• Fallen/Enemy Sign: 0%` } },
      { type: "paragraph", text: { en: `These figures should not be interpreted too literally, but they provide a useful illustration of how planetary condition influences its ability to produce positive results.`, ja: `These figures should not be interpreted too literally, but they provide a useful illustration of how planetary condition influences its ability to produce positive results.` } },
      { type: "paragraph", text: { en: `The chart below summarises these relationships.`, ja: `The chart below summarises these relationships.` } },
      { type: "paragraph", text: { en: `Please remember that the categories of Great Friend and Great Enemy depend upon temporary planetary relationships within a particular chart and are therefore not fixed.`, ja: `Please remember that the categories of Great Friend and Great Enemy depend upon temporary planetary relationships within a particular chart and are therefore not fixed.` } },
      { type: "heading", level: 3, text: { en: `Planetary Strengths by Sign Placement – Nine Categories or States in Jyotish`, ja: `Planetary Strengths by Sign Placement – Nine Categories or States in Jyotish` } },
      { type: "paragraph", text: { en: `A table showing the relationship between sign placement (Exalted, Own Sign, etc.) and resulting planetary strength in Jyotish Astrology.`, ja: `A table showing the relationship between sign placement (Exalted, Own Sign, etc.) and resulting planetary strength in Jyotish Astrology.` } },
      { type: "heading", level: 3, text: { en: `Other Factors Which Influence Planetary Strength`, ja: `Other Factors Which Influence Planetary Strength` } },
      { type: "paragraph", text: { en: `Several additional factors can modify planetary strength.`, ja: `Several additional factors can modify planetary strength.` } },
      { type: "paragraph", text: { en: `These include:`, ja: `These include:` } },
      { type: "paragraph", text: { en: `• Retrograde motion`, ja: `• Retrograde motion` } },
      { type: "paragraph", text: { en: `• Combustion`, ja: `• Combustion` } },
      { type: "paragraph", text: { en: `• Planetary War`, ja: `• Planetary War` } },
      { type: "paragraph", text: { en: `• Position in divisional charts`, ja: `• Position in divisional charts` } },
      { type: "paragraph", text: { en: `If you are completely new to Jyotish, you may wish to skip this section initially and return to it later.`, ja: `If you are completely new to Jyotish, you may wish to skip this section initially and return to it later.` } },
      { type: "heading", level: 3, text: { en: `Effects of Aspects on Planetary Strength`, ja: `Effects of Aspects on Planetary Strength` } },
      { type: "paragraph", text: { en: `Planets receiving aspects from benefic planets such as Jupiter, Venus, Mercury, and the Moon gain strength. Consequently, both their natural indications and the houses they rule are enhanced.`, ja: `Planets receiving aspects from benefic planets such as Jupiter, Venus, Mercury, and the Moon gain strength. Consequently, both their natural indications and the houses they rule are enhanced.` } },
      { type: "paragraph", text: { en: `Aspects in Jyotish are more sophisticated than those used in Western Astrology.`, ja: `Aspects in Jyotish are more sophisticated than those used in Western Astrology.` } },
      { type: "paragraph", text: { en: `Planets receiving aspects from malefics such as Mars and Saturn become weakened. As a result, their indications and the houses they govern may experience challenges.`, ja: `Planets receiving aspects from malefics such as Mars and Saturn become weakened. As a result, their indications and the houses they govern may experience challenges.` } },
      { type: "paragraph", text: { en: `Note: Rahu and Ketu do not cast aspects.`, ja: `Note: Rahu and Ketu do not cast aspects.` } },
      { type: "heading", level: 3, text: { en: `Effect of Combust Planets in Vedic Astrology`, ja: `Effect of Combust Planets in Vedic Astrology` } },
      { type: "paragraph", text: { en: `When a planet comes too close to the Sun, it can become combust, meaning its ability to produce positive results is reduced.`, ja: `When a planet comes too close to the Sun, it can become combust, meaning its ability to produce positive results is reduced.` } },
      { type: "paragraph", text: { en: `This negatively affects both its natural indications and the houses it rules.`, ja: `This negatively affects both its natural indications and the houses it rules.` } },
      { type: "paragraph", text: { en: `Mercury frequently becomes combust because it always remains relatively close to the Sun. Venus also commonly experiences combustion. When Venus appears as the Morning Star before sunrise, it is necessarily positioned fairly close to the Sun.`, ja: `Mercury frequently becomes combust because it always remains relatively close to the Sun. Venus also commonly experiences combustion. When Venus appears as the Morning Star before sunrise, it is necessarily positioned fairly close to the Sun.` } },
      { type: "paragraph", text: { en: `Generally, combustion occurs when a planet is within approximately 10 to 15 degrees of the Sun. However, the precise range varies according to the planet involved and whether it is moving direct or retrograde.`, ja: `Generally, combustion occurs when a planet is within approximately 10 to 15 degrees of the Sun. However, the precise range varies according to the planet involved and whether it is moving direct or retrograde.` } },
      { type: "paragraph", text: { en: `Rahu and Ketu never become combust.`, ja: `Rahu and Ketu never become combust.` } },
      { type: "paragraph", text: { en: `Therefore, whenever a planet lies very close to the Sun, combustion should be investigated further.`, ja: `Therefore, whenever a planet lies very close to the Sun, combustion should be investigated further.` } },
      { type: "heading", level: 3, text: { en: `Effect of Retrograde Planets in Jyotish`, ja: `Effect of Retrograde Planets in Jyotish` } },
      { type: "paragraph", text: { en: `Another important factor influencing planetary status is retrograde motion.`, ja: `Another important factor influencing planetary status is retrograde motion.` } },
      { type: "paragraph", text: { en: `No physical planet actually reverses its orbit around the Sun. However, due to the relative motions of Earth and the planets, they may appear to move backwards against the background of the fixed stars and constellations. This apparent reversal is known as retrograde motion.`, ja: `No physical planet actually reverses its orbit around the Sun. However, due to the relative motions of Earth and the planets, they may appear to move backwards against the background of the fixed stars and constellations. This apparent reversal is known as retrograde motion.` } },
      { type: "paragraph", text: { en: `Although astrologers differ somewhat in their interpretations, the general consensus is that retrograde planets gain strength. Since strength is usually regarded as beneficial in Jyotish, retrogression is often viewed positively.`, ja: `Although astrologers differ somewhat in their interpretations, the general consensus is that retrograde planets gain strength. Since strength is usually regarded as beneficial in Jyotish, retrogression is often viewed positively.` } },
      { type: "paragraph", text: { en: `This view is supported by the observation that retrograde planets generally need to move closer to the Sun before combustion occurs.`, ja: `This view is supported by the observation that retrograde planets generally need to move closer to the Sun before combustion occurs.` } },
      { type: "heading", level: 3, text: { en: `Planets with Vargottama Status`, ja: `Planets with Vargottama Status` } },
      { type: "paragraph", text: { en: `Vargottama is another factor that modifies planetary condition.`, ja: `Vargottama is another factor that modifies planetary condition.` } },
      { type: "paragraph", text: { en: `Beginners are often advised not to focus heavily on the divisional charts or Vargas. Nevertheless, the Navamsha chart (the ninth divisional chart) is especially important, not only for marriage and partnerships but also for assessing planetary strength.`, ja: `Beginners are often advised not to focus heavily on the divisional charts or Vargas. Nevertheless, the Navamsha chart (the ninth divisional chart) is especially important, not only for marriage and partnerships but also for assessing planetary strength.` } },
      { type: "paragraph", text: { en: `A planet occupying the same sign in both the main birth chart and the Navamsha chart is said to be Vargottama.`, ja: `A planet occupying the same sign in both the main birth chart and the Navamsha chart is said to be Vargottama.` } },
      { type: "paragraph", text: { en: `This condition strengthens the planet considerably and is generally regarded as being at least equivalent to Own Sign status.`, ja: `This condition strengthens the planet considerably and is generally regarded as being at least equivalent to Own Sign status.` } },
      { type: "paragraph", text: { en: `If a planet occupies its exaltation sign or own sign in both charts, its beneficial influence becomes even more powerful.`, ja: `If a planet occupies its exaltation sign or own sign in both charts, its beneficial influence becomes even more powerful.` } },
      { type: "heading", level: 3, text: { en: `Planetary War in Jyotish`, ja: `Planetary War in Jyotish` } },
      { type: "paragraph", text: { en: `Planetary War occurs when two or more planets come into extremely close conjunction, usually within approximately one degree of each other.`, ja: `Planetary War occurs when two or more planets come into extremely close conjunction, usually within approximately one degree of each other.` } },
      { type: "paragraph", text: { en: `Most Jyotish texts state that the planet at the lower degree wins the war, while the planet at the higher degree loses some of its ability to produce positive results.`, ja: `Most Jyotish texts state that the planet at the lower degree wins the war, while the planet at the higher degree loses some of its ability to produce positive results.` } },
      { type: "paragraph", text: { en: `There is little doubt that planets positioned this closely together create significant effects. However, there remains considerable scholarly debate regarding the exact conditions required for Planetary War and the precise outcomes experienced by the planets involved.`, ja: `There is little doubt that planets positioned this closely together create significant effects. However, there remains considerable scholarly debate regarding the exact conditions required for Planetary War and the precise outcomes experienced by the planets involved.` } },
      { type: "paragraph", text: { en: `Note: The Sun, Moon, Rahu, and Ketu do not participate in Planetary War.`, ja: `Note: The Sun, Moon, Rahu, and Ketu do not participate in Planetary War.` } },
    ],
  },
  {
    id: "chart-formats",
    section: "houses",
    title: { en: `Chart Formats in Jyotish Astrology`, ja: `Chart Formats in Jyotish Astrology` },
    related: ["twelve-houses","good-bad-houses","sidereal-zodiac-p3"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Chart Formats in Jyotish Astrology`, ja: `Chart Formats in Jyotish Astrology` } },
      { type: "paragraph", text: { en: `Summary: A comparison of the two primary birth-chart formats used in Jyotish Astrology—the North Indian and South Indian systems—along with suggested adaptations for students learning Jyotish. This overview is particularly useful for beginners seeking to understand and interpret Vedic astrology charts.`, ja: `Summary: A comparison of the two primary birth-chart formats used in Jyotish Astrology—the North Indian and South Indian systems—along with suggested adaptations for students learning Jyotish. This overview is particularly useful for beginners seeking to understand and interpret Vedic astrology charts.` } },
      { type: "heading", level: 3, text: { en: `North Indian and South Indian Chart Formats Compared`, ja: `North Indian and South Indian Chart Formats Compared` } },
      { type: "paragraph", text: { en: `Most Western astrologers use a circular horoscope format, but this style of chart is not commonly used in Jyotish.`, ja: `Most Western astrologers use a circular horoscope format, but this style of chart is not commonly used in Jyotish.` } },
      { type: "paragraph", text: { en: `In Vedic Astrology, there are two main chart formats: the North Indian system and the South Indian system. For newcomers to the subject, this can initially be confusing because the charts appear very different from one another. However, both formats display exactly the same astrological information—they simply present it in different ways.`, ja: `In Vedic Astrology, there are two main chart formats: the North Indian system and the South Indian system. For newcomers to the subject, this can initially be confusing because the charts appear very different from one another. However, both formats display exactly the same astrological information—they simply present it in different ways.` } },
      { type: "paragraph", text: { en: `The diamond-shaped grid is predominantly used in North India, while the rectangular grid is more commonly used in South India. Both charts shown in the illustration below contain identical astrological data.`, ja: `The diamond-shaped grid is predominantly used in North India, while the rectangular grid is more commonly used in South India. Both charts shown in the illustration below contain identical astrological data.` } },
      { type: "paragraph", text: { en: `In the North Indian format, the Ascendant is always placed in the upper diamond-shaped section, and the zodiac signs are often numbered from 1 to 12, corresponding to Aries through Pisces. In the example horoscope shown, the Ascendant is in Pisces, the 12th sign, with both Jupiter and Venus positioned in the Ascendant. Rahu is located in Cancer, the 4th sign, which corresponds to the 5th house in this particular chart, and so on.`, ja: `In the North Indian format, the Ascendant is always placed in the upper diamond-shaped section, and the zodiac signs are often numbered from 1 to 12, corresponding to Aries through Pisces. In the example horoscope shown, the Ascendant is in Pisces, the 12th sign, with both Jupiter and Venus positioned in the Ascendant. Rahu is located in Cancer, the 4th sign, which corresponds to the 5th house in this particular chart, and so on.` } },
      { type: "heading", level: 3, text: { en: `Comparison between North and South Indian Jyotish Chart Formats`, ja: `Comparison between North and South Indian Jyotish Chart Formats` } },
      { type: "heading", level: 3, text: { en: `Comparison between North and South Indian Jyotish Chart Formats`, ja: `Comparison between North and South Indian Jyotish Chart Formats` } },
      { type: "paragraph", text: { en: `The zodiac signs used in Jyotish have the same names as those found in Western Astrology, such as Aries, Taurus, Gemini, and so forth. However, their actual positions in the sky differ from those used in Western astrology.`, ja: `The zodiac signs used in Jyotish have the same names as those found in Western Astrology, such as Aries, Taurus, Gemini, and so forth. However, their actual positions in the sky differ from those used in Western astrology.` } },
      { type: "paragraph", text: { en: `This difference arises because Vedic Astrology references the zodiac signs against the background of the fixed stars and therefore uses the Sidereal Zodiac, whereas Western Astrology generally uses the Tropical Zodiac.`, ja: `This difference arises because Vedic Astrology references the zodiac signs against the background of the fixed stars and therefore uses the Sidereal Zodiac, whereas Western Astrology generally uses the Tropical Zodiac.` } },
      { type: "paragraph", text: { en: `At present, there is approximately a 24-degree difference between these two systems. The Tropical Zodiac takes the Spring Equinox as the zero-degree reference point for Aries, but this reference gradually shifts against the fixed stars due to the phenomenon known as the precession of the equinoxes.`, ja: `At present, there is approximately a 24-degree difference between these two systems. The Tropical Zodiac takes the Spring Equinox as the zero-degree reference point for Aries, but this reference gradually shifts against the fixed stars due to the phenomenon known as the precession of the equinoxes.` } },
      { type: "paragraph", text: { en: `For those beginning their study of Jyotish, I believe a slightly modified version of the South Indian rectangular chart format is generally easier for Western students to understand and work with (see the diagram at the end of this article).`, ja: `For those beginning their study of Jyotish, I believe a slightly modified version of the South Indian rectangular chart format is generally easier for Western students to understand and work with (see the diagram at the end of this article).` } },
      { type: "heading", level: 3, text: { en: `South Indian Jyotish Birth-chart Format`, ja: `South Indian Jyotish Birth-chart Format` } },
      { type: "paragraph", text: { en: `In the South Indian chart system, each zodiac sign always occupies the same fixed position within the chart. For example, Pisces remains in the upper-left box, while Virgo always occupies the lower-right box.`, ja: `In the South Indian chart system, each zodiac sign always occupies the same fixed position within the chart. For example, Pisces remains in the upper-left box, while Virgo always occupies the lower-right box.` } },
      { type: "paragraph", text: { en: `The zodiac signs are counted in a clockwise direction around the rectangular chart: Aries (1), Taurus (2), Gemini (3), Cancer (4), Leo (5), and so on.`, ja: `The zodiac signs are counted in a clockwise direction around the rectangular chart: Aries (1), Taurus (2), Gemini (3), Cancer (4), Leo (5), and so on.` } },
      { type: "paragraph", text: { en: `The Ascendant is indicated by a single diagonal line placed within the relevant sign. This remains the same regardless of the exact Ascendant degree. For example, an Ascendant at 1° Leo and an Ascendant at 29° Leo are both represented identically.`, ja: `The Ascendant is indicated by a single diagonal line placed within the relevant sign. This remains the same regardless of the exact Ascendant degree. For example, an Ascendant at 1° Leo and an Ascendant at 29° Leo are both represented identically.` } },
      { type: "paragraph", text: { en: `In this system, houses correspond exactly to signs and are counted clockwise from the Ascendant. Thus, if the Ascendant is in Leo—whether at 1 degree or 29 degrees—the entire sign of Leo becomes the 1st house, the whole sign of Virgo becomes the 2nd house, Libra becomes the 3rd house, and so forth.`, ja: `In this system, houses correspond exactly to signs and are counted clockwise from the Ascendant. Thus, if the Ascendant is in Leo—whether at 1 degree or 29 degrees—the entire sign of Leo becomes the 1st house, the whole sign of Virgo becomes the 2nd house, Libra becomes the 3rd house, and so forth.` } },
      { type: "heading", level: 3, text: { en: `South Indian Vedic Astrology Chart Format`, ja: `South Indian Vedic Astrology Chart Format` } },
      { type: "heading", level: 3, text: { en: `South Indian Vedic Astrology Chart Format`, ja: `South Indian Vedic Astrology Chart Format` } },
    ],
  },
  {
    id: "twelve-houses",
    section: "houses",
    title: { en: `The Twelve Houses and Their Indications`, ja: `The Twelve Houses and Their Indications` },
    related: ["good-bad-houses","planetary-strengths","chart-formats"],
    blocks: [
      { type: "heading", level: 2, text: { en: `The Twelve Houses and Their Indications`, ja: `The Twelve Houses and Their Indications` } },
      { type: "paragraph", text: { en: `Summary: Covers the primary indications of each of the Twelve Houses in Vedic Astrology, together with explanatory notes and House Classifications.`, ja: `Summary: Covers the primary indications of each of the Twelve Houses in Vedic Astrology, together with explanatory notes and House Classifications.` } },
      { type: "paragraph", text: { en: `This section is essential reading for students of Jyotish, as it outlines the principal areas of life governed by each of the twelve houses.`, ja: `This section is essential reading for students of Jyotish, as it outlines the principal areas of life governed by each of the twelve houses.` } },
      { type: "paragraph", text: { en: `Most chart interpretations are conducted on a house-by-house basis, making a sound understanding of the houses and their indications absolutely essential.`, ja: `Most chart interpretations are conducted on a house-by-house basis, making a sound understanding of the houses and their indications absolutely essential.` } },
      { type: "paragraph", text: { en: `Traditional Jyotish texts often provide extensive lists of matters associated with each house. However, in this article, I have attempted to remain concise and focus on the most important indications.`, ja: `Traditional Jyotish texts often provide extensive lists of matters associated with each house. However, in this article, I have attempted to remain concise and focus on the most important indications.` } },
      { type: "heading", level: 3, text: { en: `First House – ‘House of Body’`, ja: `First House – ‘House of Body’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Birth and early childhood`, ja: `• Birth and early childhood` } },
      { type: "paragraph", text: { en: `• Health, physical body, and vitality`, ja: `• Health, physical body, and vitality` } },
      { type: "paragraph", text: { en: `• Personality and temperament`, ja: `• Personality and temperament` } },
      { type: "paragraph", text: { en: `• Self-confidence and self-esteem`, ja: `• Self-confidence and self-esteem` } },
      { type: "paragraph", text: { en: `• Prosperity and fame`, ja: `• Prosperity and fame` } },
      { type: "paragraph", text: { en: `• Dharma – actions and activities that promote spiritual evolution`, ja: `• Dharma – actions and activities that promote spiritual evolution` } },
      { type: "paragraph", text: { en: `The 1st house governs several key areas of life, and a strong [1] first house tends to improve the overall quality of the horoscope.`, ja: `The 1st house governs several key areas of life, and a strong [1] first house tends to improve the overall quality of the horoscope.` } },
      { type: "paragraph", text: { en: `It represents the self and all matters connected with our identity. The ruler of the 1st house plays a major role in shaping our personality, behaviour, and natural tendencies.`, ja: `It represents the self and all matters connected with our identity. The ruler of the 1st house plays a major role in shaping our personality, behaviour, and natural tendencies.` } },
      { type: "paragraph", text: { en: `House Classification: Kendra / Dharma (Angular House / Action)`, ja: `House Classification: Kendra / Dharma (Angular House / Action)` } },
      { type: "paragraph", text: { en: `House Indicator [2]: Sun`, ja: `House Indicator [2]: Sun` } },
      { type: "heading", level: 3, text: { en: `Second House – ‘House of Wealth’`, ja: `Second House – ‘House of Wealth’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Accumulated wealth and finances`, ja: `• Accumulated wealth and finances` } },
      { type: "paragraph", text: { en: `• Speech and verbal communication`, ja: `• Speech and verbal communication` } },
      { type: "paragraph", text: { en: `• Family life`, ja: `• Family life` } },
      { type: "paragraph", text: { en: `The 2nd house is the principal indicator of the wealth and financial resources we accumulate throughout life.`, ja: `The 2nd house is the principal indicator of the wealth and financial resources we accumulate throughout life.` } },
      { type: "paragraph", text: { en: `It is also closely associated with speech and verbal expression, making it important in matters relating to education and communication.`, ja: `It is also closely associated with speech and verbal expression, making it important in matters relating to education and communication.` } },
      { type: "paragraph", text: { en: `House Classification: Artha (Wealth)`, ja: `House Classification: Artha (Wealth)` } },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, ja: `House Indicator: Jupiter` } },
      { type: "heading", level: 3, text: { en: `Third House – ‘House of Brothers, Sisters and Desires’`, ja: `Third House – ‘House of Brothers, Sisters and Desires’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Brothers and sisters`, ja: `• Brothers and sisters` } },
      { type: "paragraph", text: { en: `• Desires and ambitions`, ja: `• Desires and ambitions` } },
      { type: "paragraph", text: { en: `• Courage`, ja: `• Courage` } },
      { type: "paragraph", text: { en: `• Personal effort and initiative`, ja: `• Personal effort and initiative` } },
      { type: "paragraph", text: { en: `• Communication`, ja: `• Communication` } },
      { type: "paragraph", text: { en: `A favourable 3rd house brings happiness through brothers and sisters. Siblings may be supportive and beneficial, and relationships with them are often harmonious. Some astrologers restrict the indications of the 3rd house specifically to younger siblings.`, ja: `A favourable 3rd house brings happiness through brothers and sisters. Siblings may be supportive and beneficial, and relationships with them are often harmonious. Some astrologers restrict the indications of the 3rd house specifically to younger siblings.` } },
      { type: "paragraph", text: { en: `The 3rd is an Upachaya, or "growing" house, where malefic planets [4] generally perform well unless debilitated or otherwise weakened.`, ja: `The 3rd is an Upachaya, or "growing" house, where malefic planets [4] generally perform well unless debilitated or otherwise weakened.` } },
      { type: "paragraph", text: { en: `House Classification: Upachaya / Kama (Growing House / Desire)`, ja: `House Classification: Upachaya / Kama (Growing House / Desire)` } },
      { type: "paragraph", text: { en: `House Indicator: Mars`, ja: `House Indicator: Mars` } },
      { type: "heading", level: 3, text: { en: `Fourth House – ‘House of Happiness and Comforts’`, ja: `Fourth House – ‘House of Happiness and Comforts’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Happiness and comforts`, ja: `• Happiness and comforts` } },
      { type: "paragraph", text: { en: `• The affairs, well-being, and relationship with our mother`, ja: `• The affairs, well-being, and relationship with our mother` } },
      { type: "paragraph", text: { en: `• Fixed assets such as property, land, and buildings`, ja: `• Fixed assets such as property, land, and buildings` } },
      { type: "paragraph", text: { en: `• Friends and relatives`, ja: `• Friends and relatives` } },
      { type: "paragraph", text: { en: `The 4th house governs the home environment and our mother. The condition of the Moon also provides important information regarding the mother's well-being.`, ja: `The 4th house governs the home environment and our mother. The condition of the Moon also provides important information regarding the mother's well-being.` } },
      { type: "paragraph", text: { en: `This house reflects our overall level of happiness, contentment, and satisfaction in life, whether physical, emotional, spiritual, or financial.`, ja: `This house reflects our overall level of happiness, contentment, and satisfaction in life, whether physical, emotional, spiritual, or financial.` } },
      { type: "paragraph", text: { en: `House Classification: Kendra / Moksha (Angular / Liberation)`, ja: `House Classification: Kendra / Moksha (Angular / Liberation)` } },
      { type: "paragraph", text: { en: `House Indicator: Moon`, ja: `House Indicator: Moon` } },
      { type: "heading", level: 3, text: { en: `Fifth House – ‘House of Children’`, ja: `Fifth House – ‘House of Children’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Children, intelligence, education, and the mind`, ja: `• Children, intelligence, education, and the mind` } },
      { type: "paragraph", text: { en: `• Spiritual practices and religious knowledge`, ja: `• Spiritual practices and religious knowledge` } },
      { type: "paragraph", text: { en: `• Past-life credit (positive returning karmas)`, ja: `• Past-life credit (positive returning karmas)` } },
      { type: "paragraph", text: { en: `• Investment and speculation`, ja: `• Investment and speculation` } },
      { type: "paragraph", text: { en: `The 5th house rules children and provides information regarding offspring, their number, and the happiness they bring into our lives.`, ja: `The 5th house rules children and provides information regarding offspring, their number, and the happiness they bring into our lives.` } },
      { type: "paragraph", text: { en: `It also governs intelligence, common sense, learning ability, and education.`, ja: `It also governs intelligence, common sense, learning ability, and education.` } },
      { type: "paragraph", text: { en: `A strong 5th house is frequently found in the charts of virtuous individuals who have made significant spiritual or personal progress.`, ja: `A strong 5th house is frequently found in the charts of virtuous individuals who have made significant spiritual or personal progress.` } },
      { type: "paragraph", text: { en: `The 5th is considered a highly auspicious house, and planets occupying it generally benefit from the placement.`, ja: `The 5th is considered a highly auspicious house, and planets occupying it generally benefit from the placement.` } },
      { type: "paragraph", text: { en: `House Classification: Trikona / Dharma (Trinal / Action)`, ja: `House Classification: Trikona / Dharma (Trinal / Action)` } },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, ja: `House Indicator: Jupiter` } },
      { type: "heading", level: 3, text: { en: `Sixth House – ‘House of Enemies’`, ja: `Sixth House – ‘House of Enemies’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Enemies, competitors, jealous individuals, work subordinates, and obstacles`, ja: `• Enemies, competitors, jealous individuals, work subordinates, and obstacles` } },
      { type: "paragraph", text: { en: `• Illness and disease`, ja: `• Illness and disease` } },
      { type: "paragraph", text: { en: `• Worries and anxieties`, ja: `• Worries and anxieties` } },
      { type: "paragraph", text: { en: `In this context, "enemies" can include competitors or people who may rise to a higher status than us within an organisation.`, ja: `In this context, "enemies" can include competitors or people who may rise to a higher status than us within an organisation.` } },
      { type: "paragraph", text: { en: `A powerful 6th house often enables a person to excel and reach the top of their chosen profession.`, ja: `A powerful 6th house often enables a person to excel and reach the top of their chosen profession.` } },
      { type: "paragraph", text: { en: `The 6th is another Upachaya or growing house, meaning that the problems it indicates can improve with time. For example, a health issue shown by the 6th house may be present during childhood but disappear later in life.`, ja: `The 6th is another Upachaya or growing house, meaning that the problems it indicates can improve with time. For example, a health issue shown by the 6th house may be present during childhood but disappear later in life.` } },
      { type: "paragraph", text: { en: `Malefic planets and their natural significations generally function reasonably well in the 6th house.`, ja: `Malefic planets and their natural significations generally function reasonably well in the 6th house.` } },
      { type: "paragraph", text: { en: `However, the houses ruled by planets occupying the 6th are often disturbed to some extent.`, ja: `However, the houses ruled by planets occupying the 6th are often disturbed to some extent.` } },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Upachaya / Artha (Negative / Growing / Wealth)`, ja: `House Classification: Dusthana / Upachaya / Artha (Negative / Growing / Wealth)` } },
      { type: "paragraph", text: { en: `House Indicator: Mars`, ja: `House Indicator: Mars` } },
      { type: "heading", level: 3, text: { en: `Seventh House – ‘House of Marriage and Partnerships’`, ja: `Seventh House – ‘House of Marriage and Partnerships’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Marriage and married life`, ja: `• Marriage and married life` } },
      { type: "paragraph", text: { en: `• Spouse or partner`, ja: `• Spouse or partner` } },
      { type: "paragraph", text: { en: `• Sexual passions`, ja: `• Sexual passions` } },
      { type: "paragraph", text: { en: `• Partnerships of all kinds, including business partnerships`, ja: `• Partnerships of all kinds, including business partnerships` } },
      { type: "paragraph", text: { en: `The 7th house reveals the quality of married life and the well-being of one's partner.`, ja: `The 7th house reveals the quality of married life and the well-being of one's partner.` } },
      { type: "paragraph", text: { en: `Additional insights regarding marriage can be obtained by treating the Moon's sign as the Ascendant and examining the planets located in the 7th house from the Moon.`, ja: `Additional insights regarding marriage can be obtained by treating the Moon's sign as the Ascendant and examining the planets located in the 7th house from the Moon.` } },
      { type: "paragraph", text: { en: `A strong Navamsa chart [5] is highly beneficial for relationships and marriage.`, ja: `A strong Navamsa chart [5] is highly beneficial for relationships and marriage.` } },
      { type: "paragraph", text: { en: `The 7th house also governs certain aspects of travel.`, ja: `The 7th house also governs certain aspects of travel.` } },
      { type: "paragraph", text: { en: `House Classification: Kendra / Kama (Angular / Desire)`, ja: `House Classification: Kendra / Kama (Angular / Desire)` } },
      { type: "paragraph", text: { en: `House Indicator: Venus`, ja: `House Indicator: Venus` } },
      { type: "heading", level: 3, text: { en: `Eighth House – ‘House of Transformation’`, ja: `Eighth House – ‘House of Transformation’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Life, longevity, and death`, ja: `• Life, longevity, and death` } },
      { type: "paragraph", text: { en: `• Wills, inheritances, and legacies`, ja: `• Wills, inheritances, and legacies` } },
      { type: "paragraph", text: { en: `• Intuition, occult studies, and hidden knowledge`, ja: `• Intuition, occult studies, and hidden knowledge` } },
      { type: "paragraph", text: { en: `• Secret and esoteric subjects`, ja: `• Secret and esoteric subjects` } },
      { type: "paragraph", text: { en: `The 8th house is often referred to as the "House of Death" because it governs the nature and circumstances surrounding death.`, ja: `The 8th house is often referred to as the "House of Death" because it governs the nature and circumstances surrounding death.` } },
      { type: "paragraph", text: { en: `However, a strong 8th house, particularly when supported by a well-placed Saturn, can indicate a long, active, and energetic life.`, ja: `However, a strong 8th house, particularly when supported by a well-placed Saturn, can indicate a long, active, and energetic life.` } },
      { type: "paragraph", text: { en: `The 8th is also a Moksha house and often stimulates interest in personal transformation and spiritual growth.`, ja: `The 8th is also a Moksha house and often stimulates interest in personal transformation and spiritual growth.` } },
      { type: "paragraph", text: { en: `According to some astrologers, it additionally governs chronic illnesses, long-term mental and physical conditions, and sexually transmitted diseases.`, ja: `According to some astrologers, it additionally governs chronic illnesses, long-term mental and physical conditions, and sexually transmitted diseases.` } },
      { type: "paragraph", text: { en: `The 8th generally weakens planets occupying it (although exceptions exist), along with the houses ruled by those planets.`, ja: `The 8th generally weakens planets occupying it (although exceptions exist), along with the houses ruled by those planets.` } },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Moksha (Negative / Liberation)`, ja: `House Classification: Dusthana / Moksha (Negative / Liberation)` } },
      { type: "paragraph", text: { en: `House Indicator: Saturn`, ja: `House Indicator: Saturn` } },
      { type: "heading", level: 3, text: { en: `Ninth House – ‘House of Fortune’`, ja: `Ninth House – ‘House of Fortune’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Luck, fortune, and prosperity`, ja: `• Luck, fortune, and prosperity` } },
      { type: "paragraph", text: { en: `• Religion, faith, worship, spiritual teachers, law, and higher knowledge`, ja: `• Religion, faith, worship, spiritual teachers, law, and higher knowledge` } },
      { type: "paragraph", text: { en: `• Certain aspects of the relationship with one's father`, ja: `• Certain aspects of the relationship with one's father` } },
      { type: "paragraph", text: { en: `• Pilgrimages and long-distance travel`, ja: `• Pilgrimages and long-distance travel` } },
      { type: "paragraph", text: { en: `The 9th house is of equal importance to the 1st house.`, ja: `The 9th house is of equal importance to the 1st house.` } },
      { type: "paragraph", text: { en: `It primarily signifies luck, fortune, and blessings in life.`, ja: `It primarily signifies luck, fortune, and blessings in life.` } },
      { type: "paragraph", text: { en: `The 9th is generally regarded as the most auspicious house in the horoscope. Planets placed here tend to perform exceptionally well, and the ruler of the 9th carries a highly positive energy wherever it is located.`, ja: `The 9th is generally regarded as the most auspicious house in the horoscope. Planets placed here tend to perform exceptionally well, and the ruler of the 9th carries a highly positive energy wherever it is located.` } },
      { type: "paragraph", text: { en: `Some astrologers associate past-life credit more strongly with the 9th house than with the 5th.`, ja: `Some astrologers associate past-life credit more strongly with the 9th house than with the 5th.` } },
      { type: "paragraph", text: { en: `A strong 9th house can bestow tremendous good fortune and a sense of divine grace.`, ja: `A strong 9th house can bestow tremendous good fortune and a sense of divine grace.` } },
      { type: "paragraph", text: { en: `A person's relationship with their spiritual teacher is seen through the 9th house. Traditionally in India, the father often fulfilled this role during childhood before a spiritual guru was encountered later in life. Consequently, some aspects of the father-child relationship are also examined through the 9th house.`, ja: `A person's relationship with their spiritual teacher is seen through the 9th house. Traditionally in India, the father often fulfilled this role during childhood before a spiritual guru was encountered later in life. Consequently, some aspects of the father-child relationship are also examined through the 9th house.` } },
      { type: "paragraph", text: { en: `House Classification: Trikona / Dharma (Trinal / Action)`, ja: `House Classification: Trikona / Dharma (Trinal / Action)` } },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, ja: `House Indicator: Jupiter` } },
      { type: "heading", level: 3, text: { en: `Tenth House – ‘House of Status and Power’`, ja: `Tenth House – ‘House of Status and Power’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Career, status, and reputation`, ja: `• Career, status, and reputation` } },
      { type: "paragraph", text: { en: `• Fame and professional achievement`, ja: `• Fame and professional achievement` } },
      { type: "paragraph", text: { en: `• Authority figures, government officials, and institutions`, ja: `• Authority figures, government officials, and institutions` } },
      { type: "paragraph", text: { en: `• The status, authority, and influence of the father`, ja: `• The status, authority, and influence of the father` } },
      { type: "paragraph", text: { en: `The 10th house indicates the degree of success, recognition, and professional standing we may achieve in our chosen career.`, ja: `The 10th house indicates the degree of success, recognition, and professional standing we may achieve in our chosen career.` } },
      { type: "paragraph", text: { en: `It is an Upachaya or growing house, where malefic planets can perform well, provided they are not debilitated or adversely affected.`, ja: `It is an Upachaya or growing house, where malefic planets can perform well, provided they are not debilitated or adversely affected.` } },
      { type: "paragraph", text: { en: `Many important factors relating to a person's father are also assessed from the 10th house.`, ja: `Many important factors relating to a person's father are also assessed from the 10th house.` } },
      { type: "paragraph", text: { en: `House Classification: Kendra / Upachaya / Artha (Angular / Growing / Wealth)`, ja: `House Classification: Kendra / Upachaya / Artha (Angular / Growing / Wealth)` } },
      { type: "paragraph", text: { en: `House Indicator: Mercury`, ja: `House Indicator: Mercury` } },
      { type: "heading", level: 3, text: { en: `Eleventh House – ‘House of Gains, Profits and Desires’`, ja: `Eleventh House – ‘House of Gains, Profits and Desires’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Gains, profits, and income`, ja: `• Gains, profits, and income` } },
      { type: "paragraph", text: { en: `• Desires, wishes, ambitions, and opportunities`, ja: `• Desires, wishes, ambitions, and opportunities` } },
      { type: "paragraph", text: { en: `The 11th house differs from the 2nd in that it governs gains and profits obtained by any means. Therefore, even if the 2nd house is weak, substantial income may still be generated, although this does not necessarily result in accumulated wealth.`, ja: `The 11th house differs from the 2nd in that it governs gains and profits obtained by any means. Therefore, even if the 2nd house is weak, substantial income may still be generated, although this does not necessarily result in accumulated wealth.` } },
      { type: "paragraph", text: { en: `The 11th house governs the fulfilment of major desires and ambitions. A strong 11th brings opportunities that enable a person to realise their goals.`, ja: `The 11th house governs the fulfilment of major desires and ambitions. A strong 11th brings opportunities that enable a person to realise their goals.` } },
      { type: "paragraph", text: { en: `Like other Upachaya houses, malefic planets can eventually produce favourable results here.`, ja: `Like other Upachaya houses, malefic planets can eventually produce favourable results here.` } },
      { type: "paragraph", text: { en: `House Classification: Upachaya / Kama (Growing / Desire)`, ja: `House Classification: Upachaya / Kama (Growing / Desire)` } },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, ja: `House Indicator: Jupiter` } },
      { type: "heading", level: 3, text: { en: `Twelfth House – ‘House of Loss and Expenditure’`, ja: `Twelfth House – ‘House of Loss and Expenditure’` } },
      { type: "heading", level: 3, text: { en: `House Indications:`, ja: `House Indications:` } },
      { type: "paragraph", text: { en: `• Expenditure, financial loss, and waste`, ja: `• Expenditure, financial loss, and waste` } },
      { type: "paragraph", text: { en: `• Misfortune`, ja: `• Misfortune` } },
      { type: "paragraph", text: { en: `• Salvation, liberation, and enlightenment`, ja: `• Salvation, liberation, and enlightenment` } },
      { type: "paragraph", text: { en: `• Journeys to distant lands`, ja: `• Journeys to distant lands` } },
      { type: "paragraph", text: { en: `The 12th house governs all forms of loss and expenditure.`, ja: `The 12th house governs all forms of loss and expenditure.` } },
      { type: "paragraph", text: { en: `A strong 12th house helps preserve and protect accumulated wealth.`, ja: `A strong 12th house helps preserve and protect accumulated wealth.` } },
      { type: "paragraph", text: { en: `It also indicates progress toward higher states of consciousness, spiritual development, and eventual enlightenment.`, ja: `It also indicates progress toward higher states of consciousness, spiritual development, and eventual enlightenment.` } },
      { type: "paragraph", text: { en: `Planets placed here are generally weakened (although there are exceptions), and the houses they rule may also be adversely affected.`, ja: `Planets placed here are generally weakened (although there are exceptions), and the houses they rule may also be adversely affected.` } },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Moksha (Negative / Liberation)`, ja: `House Classification: Dusthana / Moksha (Negative / Liberation)` } },
      { type: "paragraph", text: { en: `House Indicator: Saturn`, ja: `House Indicator: Saturn` } },
      { type: "heading", level: 3, text: { en: `Parts of the Body Associated with Each House`, ja: `Parts of the Body Associated with Each House` } },
      { type: "paragraph", text: { en: `Each house corresponds to a particular part of the body. When a house is significantly weakened, it may indicate potential health issues affecting the related area of the physiology.`, ja: `Each house corresponds to a particular part of the body. When a house is significantly weakened, it may indicate potential health issues affecting the related area of the physiology.` } },
      { type: "paragraph", text: { en: `House	Part of Body`, ja: `House	Part of Body` } },
      { type: "paragraph", text: { en: `1	Head`, ja: `1	Head` } },
      { type: "paragraph", text: { en: `2	Eyes, face, mouth, upper throat`, ja: `2	Eyes, face, mouth, upper throat` } },
      { type: "paragraph", text: { en: `3	Arms, shoulders, lower throat`, ja: `3	Arms, shoulders, lower throat` } },
      { type: "paragraph", text: { en: `4	Chest, heart`, ja: `4	Chest, heart` } },
      { type: "paragraph", text: { en: `5	Stomach`, ja: `5	Stomach` } },
      { type: "paragraph", text: { en: `6	Region of the navel`, ja: `6	Region of the navel` } },
      { type: "paragraph", text: { en: `7	Body below the waist`, ja: `7	Body below the waist` } },
      { type: "paragraph", text: { en: `8	Reproductive organs, anus`, ja: `8	Reproductive organs, anus` } },
      { type: "paragraph", text: { en: `9	Hips, thighs`, ja: `9	Hips, thighs` } },
      { type: "paragraph", text: { en: `10	Knees`, ja: `10	Knees` } },
      { type: "paragraph", text: { en: `11	Calves`, ja: `11	Calves` } },
      { type: "paragraph", text: { en: `12	Feet`, ja: `12	Feet` } },
      { type: "heading", level: 3, text: { en: `House Classification`, ja: `House Classification` } },
      { type: "paragraph", text: { en: `Houses 5 and 9 (Trikona) are regarded as exceptionally auspicious. Planets placed in these houses become strengthened, and the houses they rule also benefit from their placement in the 5th or 9th.`, ja: `Houses 5 and 9 (Trikona) are regarded as exceptionally auspicious. Planets placed in these houses become strengthened, and the houses they rule also benefit from their placement in the 5th or 9th.` } },
      { type: "paragraph", text: { en: `In addition, the rulers of the 5th and 9th houses—even if naturally malefic planets such as Saturn—become functional benefics and carry a positive influence wherever they are placed.`, ja: `In addition, the rulers of the 5th and 9th houses—even if naturally malefic planets such as Saturn—become functional benefics and carry a positive influence wherever they are placed.` } },
      { type: "paragraph", text: { en: `Houses 6, 8, and 12 (Dusthana) are considered challenging houses. Planets occupying them tend to become weakened, and the houses ruled by those planets may also suffer.`, ja: `Houses 6, 8, and 12 (Dusthana) are considered challenging houses. Planets occupying them tend to become weakened, and the houses ruled by those planets may also suffer.` } },
      { type: "paragraph", text: { en: `The rulers of the 6th, 8th, and 12th houses often create difficulties somewhere in the chart, even if they are naturally benefic planets such as Jupiter. This generally applies unless the planet also rules one of the auspicious houses, namely the 5th or 9th.`, ja: `The rulers of the 6th, 8th, and 12th houses often create difficulties somewhere in the chart, even if they are naturally benefic planets such as Jupiter. This generally applies unless the planet also rules one of the auspicious houses, namely the 5th or 9th.` } },
      { type: "paragraph", text: { en: `Houses 3, 6, 10, and 11 form the special category known as Upachaya or "growing" houses. Malefic planets tend to perform well in these houses and eventually produce beneficial results. Difficulties indicated by these houses often diminish with time.`, ja: `Houses 3, 6, 10, and 11 form the special category known as Upachaya or "growing" houses. Malefic planets tend to perform well in these houses and eventually produce beneficial results. Difficulties indicated by these houses often diminish with time.` } },
      { type: "paragraph", text: { en: `Houses 1, 4, 7, and 10 are known as Kendras or angular houses. Planets placed within them are strengthened.`, ja: `Houses 1, 4, 7, and 10 are known as Kendras or angular houses. Planets placed within them are strengthened.` } },
      { type: "paragraph", text: { en: `The houses are also grouped into repeating cycles of four:`, ja: `The houses are also grouped into repeating cycles of four:` } },
      { type: "paragraph", text: { en: `• Dharma (Duty and evolutionary action)`, ja: `• Dharma (Duty and evolutionary action)` } },
      { type: "paragraph", text: { en: `• Artha (Wealth)`, ja: `• Artha (Wealth)` } },
      { type: "paragraph", text: { en: `• Kama (Desire)`, ja: `• Kama (Desire)` } },
      { type: "paragraph", text: { en: `• Moksha (Liberation)`, ja: `• Moksha (Liberation)` } },
      { type: "paragraph", text: { en: `This pattern begins with the 1st house and repeats throughout the horoscope. Thus, the 5th house is Dharma, the 6th Artha, the 7th Kama, the 8th Moksha, and the cycle repeats again through the 9th to the 12th houses.`, ja: `This pattern begins with the 1st house and repeats throughout the horoscope. Thus, the 5th house is Dharma, the 6th Artha, the 7th Kama, the 8th Moksha, and the cycle repeats again through the 9th to the 12th houses.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "paragraph", text: { en: `[1] When we describe a house as "strong," we are considering factors such as the strength and status of the ruling planet (for example, Exalted or Own Sign status), the house occupied by the ruler (for example, placement in the auspicious 9th house), benefic planets occupying the house, and positive aspects from natural benefics such as Jupiter.`, ja: `[1] When we describe a house as "strong," we are considering factors such as the strength and status of the ruling planet (for example, Exalted or Own Sign status), the house occupied by the ruler (for example, placement in the auspicious 9th house), benefic planets occupying the house, and positive aspects from natural benefics such as Jupiter.` } },
      { type: "paragraph", text: { en: `[2] We can further evaluate a house by examining the condition and well-being of its indicator planet. While this is generally less important than factors such as the house ruler, occupying planets, and aspects, it can still modify our interpretation. The natural significations of the indicator planet often correspond closely with the affairs of the house. For example, Venus naturally signifies love, affection, and passion, which aligns well with the 7th house and its association with marriage and partnerships.`, ja: `[2] We can further evaluate a house by examining the condition and well-being of its indicator planet. While this is generally less important than factors such as the house ruler, occupying planets, and aspects, it can still modify our interpretation. The natural significations of the indicator planet often correspond closely with the affairs of the house. For example, Venus naturally signifies love, affection, and passion, which aligns well with the 7th house and its association with marriage and partnerships.` } },
    ],
  }
];
